body {
  margin: 0;
  background: #eef1f5;
  color: #101828;
  font-family: Inter, Arial, sans-serif;
}

.page {
  padding: 18px;
  box-sizing: border-box;
}

.print-button {
  display: block;
  margin: 0 auto 16px;
  width: 180px;
  height: 40px;
  border: 0;
  border-radius: 7px;
  background: #101828;
  color: white;
  font-weight: 800;
  cursor: pointer;
}

.labels {
  display: grid;
  gap: 16px;
  justify-content: center;
}

.label {
  width: 148mm;
  min-height: 105mm;
  background: white;
  box-sizing: border-box;
  padding: 12mm;
  border: 1px solid #d0d5dd;
  page-break-after: always;
}

.label-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  border-bottom: 2px solid #101828;
  padding-bottom: 8px;
}

.eyebrow {
  font-size: 11px;
  text-transform: uppercase;
  color: #667085;
  font-weight: 900;
}

h1 {
  margin: 3px 0 0;
  font-size: 27px;
  line-height: 1.05;
}

.counter {
  min-width: 58px;
  padding: 7px 10px;
  background: #101828;
  color: white;
  text-align: center;
  font-weight: 900;
}

.barcode-wrap {
  margin: 14px 0;
  display: flex;
  justify-content: center;
}

.barcode-wrap svg {
  max-width: 100%;
}

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
}

.box {
  border: 1px solid #d0d5dd;
  padding: 8px;
  min-height: 58px;
  box-sizing: border-box;
}

.box.wide {
  grid-column: span 2;
}

.box span {
  display: block;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 800;
  margin-bottom: 4px;
}

.box strong {
  display: block;
  font-size: 14px;
  line-height: 1.2;
}

.box small {
  display: block;
  margin-top: 3px;
  color: #475467;
  font-size: 11px;
  line-height: 1.3;
}

.note {
  margin-top: 10px;
  padding: 8px;
  border: 1px dashed #98a2b3;
  color: #475467;
  font-size: 11px;
}

.footer {
  margin-top: 12px;
  padding-top: 8px;
  border-top: 1px solid #d0d5dd;
  display: flex;
  justify-content: space-between;
  color: #667085;
  font-size: 10px;
}

.empty {
  background: white;
  padding: 28px;
  text-align: center;
  color: #667085;
}

@media print {
  body {
    background: white;
  }
  .page {
    padding: 0;
  }
  .print-button {
    display: none;
  }
  .labels {
    display: block;
  }
  .label {
    border: 0;
    margin: 0;
    width: 148mm;
    min-height: 105mm;
    box-shadow: none;
  }
}

