import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";
import JsBarcode from "https://esm.sh/jsbarcode@3.11.6";

function val(value) {
  return String(value ?? "");
}

function formatDate(value) {
  if (!value) return "";
  return new Date(value).toLocaleDateString("en-GB");
}

function Barcode({ value }) {
  const ref = React.useRef(null);

  React.useEffect(() => {
    if (!value || !ref.current) return;

    JsBarcode(ref.current, String(value), {
      format: "CODE128",
      displayValue: true,
      fontSize: 14,
      height: 64,
      margin: 0,
      width: 2
    });
  }, [value]);

  return <svg ref={ref} />;
}

function Label({ header, pack, index, total }) {
  const barcode = pack.packageBarcode || pack.packageNumber || `${header.documentNumber}-${index + 1}`;

  return (
    <section className="label">
      <div className="label-top">
        <div>
          <div className="eyebrow">Shipping Label</div>
          <h1>{pack.packageNumber || `Package ${index + 1}`}</h1>
        </div>
        <div className="counter">{index + 1} / {total}</div>
      </div>

      <div className="barcode-wrap">
        <Barcode value={barcode} />
      </div>

      <div className="grid">
        <div className="box">
          <span>Delivery note</span>
          <strong>{header.documentNumber || "-"}</strong>
          <small>{formatDate(header.documentDate)}</small>
        </div>

        <div className="box">
          <span>Sales order</span>
          <strong>{header.sourceOrderNumber || "-"}</strong>
          <small>{header.status || "-"}</small>
        </div>

        <div className="box wide">
          <span>Ship from</span>
          <strong>{header.companyName || "-"}</strong>
          <small>
            {[header.companyAddress, header.companyPostalCode, header.companyCity]
              .filter(Boolean)
              .join(", ")}
          </small>
        </div>

        <div className="box wide">
          <span>Ship to</span>
          <strong>{header.customerLegalName || header.customerName || "-"}</strong>
          <small>
            {[header.customerAddress, header.customerPostalCode, header.customerCity]
              .filter(Boolean)
              .join(", ")}
          </small>
        </div>

        <div className="box">
          <span>Warehouse</span>
          <strong>{header.warehouseCode || "-"}</strong>
          <small>{header.warehouseName || ""}</small>
        </div>

        <div className="box">
          <span>Package type</span>
          <strong>{pack.packageType || "-"}</strong>
          <small>{pack.packageStatus || "-"}</small>
        </div>

        <div className="box">
          <span>Items</span>
          <strong>{val(pack.itemCount || 0)}</strong>
          <small>Qty {val(pack.totalQuantity || 0)}</small>
        </div>

        <div className="box">
          <span>Weight</span>
          <strong>{val(pack.grossWeight || 0)} kg</strong>
          <small>Net {val(pack.netWeight || 0)} kg</small>
        </div>
      </div>

      {pack.note && <div className="note">{pack.note}</div>}

      <div className="footer">
        <span>Printed: {appsmith.model.printedAt || "-"}</span>
        <span>{appsmith.model.printedBy || ""}</span>
      </div>
    </section>
  );
}

function App() {
  const model = appsmith.model || {};
  const header = model.header || {};
  const packages = model.packages || [];

  if (!header.documentNumber) {
    return <div className="empty">No delivery label data available.</div>;
  }

  return (
    <main className="page">
      <button className="print-button" onClick={() => window.print()}>
        Print Labels
      </button>

      <div className="labels">
        {packages.map((pack, index) => (
          <Label
            key={pack.packageId || index}
            header={header}
            pack={pack}
            index={index}
            total={packages.length}
          />
        ))}
      </div>
    </main>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
